css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; overflow: hidden; }
.loader .rig { position: absolute; left: 28%; width: 44%; height: 80%; bottom: -14%; animation: sonde-rise calc(var(--loader-speed) * 4) ease-in-out infinite; }
.loader .sphere { position: absolute; left: 0; top: 0; width: 100%; height: 62%; border-radius: 50% 50% 44% 44%; background: radial-gradient(circle at 34% 30%, color-mix(in srgb, #fff 55%, var(--accent)), var(--accent)); box-shadow: inset -6px -8px 0 color-mix(in srgb, #000 10%, transparent); }
.loader .tether { position: absolute; left: 48%; top: 60%; width: 3%; height: 22%; background: color-mix(in srgb, #0f172a 45%, transparent); }
.loader .probe { position: absolute; left: 36%; bottom: 4%; width: 28%; height: 18%; border-radius: 3px; background: var(--accent-2); animation: sonde-swing calc(var(--loader-speed) * 2) ease-in-out infinite; }
.loader i { position: absolute; height: 12%; border-radius: 40%; background: color-mix(in srgb, var(--accent) 30%, transparent); animation: sonde-cloud calc(var(--loader-speed) * 4) linear infinite; }
.loader i:nth-of-type(1) { left: 2%; width: 30%; }
.loader i:nth-of-type(2) { left: 62%; width: 24%; animation-delay: calc(var(--loader-speed) * -2); }
@keyframes sonde-rise { 0% { transform: translateY(8%); opacity: 0; } 14% { opacity: 1; } 84% { opacity: 1; } 100% { transform: translateY(-116%); opacity: 0; } }
@keyframes sonde-swing { 0%, 100% { transform: rotate(-9deg); } 50% { transform: rotate(9deg); } }
@keyframes sonde-cloud { 0% { top: 110%; opacity: 0; } 15%, 80% { opacity: 1; } 100% { top: -20%; opacity: 0; } }
